CREATE OR REPLACE FUNCTION public.pos_complete_sale(p_shift_id uuid, p_operator_id uuid, p_client_op_id text, p_items jsonb, p_tenders jsonb, p_customer_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_shift public.pos_shifts;
  v_order public.commerce_orders;
  v_sku public.inv_skus;
  v_item record;
  v_component record;
  v_tender record;
  v_stock integer;
  v_available integer;
  v_required integer;
  v_unit_price numeric;
  v_subtotal numeric := 0;
  v_tender_total numeric := 0;
  v_payment_id uuid;
  v_receipt_no text;
  v_category_name text;
  v_subcategory_name text;
  v_items_payload jsonb;
BEGIN
  IF p_client_op_id IS NULL OR btrim(p_client_op_id) = '' THEN
    RAISE EXCEPTION 'client operation id is required';
  END IF;
  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'sale requires at least one item';
  END IF;
  IF jsonb_typeof(p_tenders) <> 'array' OR jsonb_array_length(p_tenders) = 0 THEN
    RAISE EXCEPTION 'sale requires at least one tender';
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE source_channel = 'pos'
     AND idempotency_key = p_client_op_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'order_id', v_order.id,
      'order_no', v_order.order_no,
      'replayed', true,
      'total_amount', v_order.total_amount
    );
  END IF;

  SELECT * INTO v_shift
    FROM public.pos_shifts
   WHERE id = p_shift_id
   FOR UPDATE;
  IF NOT FOUND OR v_shift.status <> 'open' THEN RAISE EXCEPTION 'POS shift is not open'; END IF;
  IF v_shift.operator_id <> p_operator_id THEN RAISE EXCEPTION 'POS shift belongs to another operator'; END IF;

  FOR v_item IN
    SELECT (elem->>'sku_id')::uuid AS sku_id, sum((elem->>'quantity')::integer) AS quantity
      FROM jsonb_array_elements(p_items) AS elem
     GROUP BY 1
     ORDER BY 1
  LOOP
    IF v_item.sku_id IS NULL OR v_item.quantity IS NULL OR v_item.quantity < 1 OR v_item.quantity > 999 THEN
      RAISE EXCEPTION 'sale item quantity is invalid';
    END IF;
    SELECT * INTO v_sku FROM public.inv_skus WHERE id = v_item.sku_id FOR UPDATE;
    IF NOT FOUND OR v_sku.status <> 'active' OR NOT v_sku.is_display THEN
      RAISE EXCEPTION 'SKU % is not sellable', v_item.sku_id;
    END IF;
    IF v_sku.kind = 'single' AND v_sku.is_custom_price AND v_item.quantity <> 1 THEN
      RAISE EXCEPTION 'custom SKU quantity must be one';
    END IF;
    v_available := public.sales_sku_available_qty(v_sku.id, v_shift.location_id);
    IF v_available < v_item.quantity THEN
      RAISE EXCEPTION 'SKU % has insufficient available stock', v_sku.id;
    END IF;
    v_subtotal := v_subtotal + v_sku.price_tier * v_item.quantity;
  END LOOP;

  FOR v_tender IN
    SELECT tender.provider, tender.amount, tender.provider_transaction_id
      FROM jsonb_to_recordset(p_tenders)
        AS tender(provider text, amount numeric, provider_transaction_id text)
  LOOP
    IF v_tender.provider NOT IN ('cash','wechat','alipay','bank_card','store_credit','manual') THEN
      RAISE EXCEPTION 'unsupported tender provider';
    END IF;
    IF v_tender.amount IS NULL OR v_tender.amount <= 0 THEN
      RAISE EXCEPTION 'tender amount is invalid';
    END IF;
    v_tender_total := v_tender_total + v_tender.amount;
  END LOOP;
  IF round(v_tender_total, 2) <> round(v_subtotal, 2) THEN
    RAISE EXCEPTION 'tender total does not match sale total';
  END IF;

  INSERT INTO public.commerce_orders (
    user_id, source_channel, fulfillment_method, sale_location_id, operator_id,
    customer_id, pos_shift_id, payment_status, order_status, subtotal,
    total_amount, recipient_name, recipient_phone, shipping_address,
    courier_provider, courier_service_code, idempotency_key,
    reservation_expires_at, paid_at, completed_at, customer_note
  ) VALUES (
    NULL, 'pos', 'carryout', v_shift.location_id, p_operator_id,
    p_customer_id, p_shift_id, 'paid', 'completed', v_subtotal,
    v_subtotal, NULL, NULL, NULL, NULL, NULL, p_client_op_id,
    now(), now(), now(), p_note
  ) RETURNING * INTO v_order;

  FOR v_item IN
    SELECT (elem->>'sku_id')::uuid AS sku_id,
           (elem->>'quantity')::integer AS quantity,
           nullif(btrim(coalesce(elem->>'subcategory_code', '')), '') AS subcategory_code,
           ord
      FROM jsonb_array_elements(p_items) WITH ORDINALITY AS t(elem, ord)
     ORDER BY ord
  LOOP
    SELECT * INTO v_sku FROM public.inv_skus WHERE id = v_item.sku_id FOR UPDATE;
    v_unit_price := v_sku.price_tier;

    SELECT name INTO v_category_name FROM public.inv_categories WHERE code = v_sku.category;

    v_subcategory_name := NULL;
    IF v_item.subcategory_code IS NOT NULL THEN
      SELECT child.name INTO v_subcategory_name
        FROM public.inv_categories child
        JOIN public.inv_categories root ON root.id = child.parent_id
       WHERE child.code = v_item.subcategory_code
         AND child.is_active
         AND root.code = v_sku.category;
      IF v_subcategory_name IS NULL THEN
        RAISE EXCEPTION 'subcategory % is not valid for SKU %', v_item.subcategory_code, v_sku.id;
      END IF;
    END IF;

    INSERT INTO public.commerce_order_items (
      order_id, listing_id, sku_id, location_id, epc, title_snapshot,
      image_snapshot, condition_snapshot, unit_price, quantity, line_total,
      category_code, category_name_snapshot, subcategory_code, subcategory_name_snapshot
    )
    VALUES (
      v_order.id, NULL, v_sku.id, v_shift.location_id,
      CASE WHEN v_sku.kind = 'single' AND v_sku.is_custom_price THEN v_sku.epc ELSE NULL END,
      v_sku.name, v_sku.image_url, v_sku.grade, v_unit_price, v_item.quantity,
      v_unit_price * v_item.quantity,
      v_sku.category, coalesce(v_category_name, v_sku.category),
      v_item.subcategory_code, v_subcategory_name
    );

    IF v_sku.kind = 'bundle' THEN
      IF jsonb_typeof(v_sku.bundle_items) <> 'array' OR jsonb_array_length(v_sku.bundle_items) = 0 THEN
        RAISE EXCEPTION 'bundle SKU % has no components', v_sku.id;
      END IF;
      FOR v_component IN
        SELECT component.sku_id, component.qty
          FROM jsonb_to_recordset(v_sku.bundle_items) AS component(sku_id uuid, qty integer)
         ORDER BY component.sku_id
      LOOP
        v_required := v_item.quantity * v_component.qty;
        SELECT qty INTO v_stock
          FROM public.inv_stocks
         WHERE sku_id = v_component.sku_id AND location_id = v_shift.location_id
         FOR UPDATE;
        IF coalesce(v_stock, 0) < v_required THEN
          RAISE EXCEPTION 'bundle component % is out of stock', v_component.sku_id;
        END IF;
        PERFORM public.inv_apply_movement(
          v_component.sku_id, v_shift.location_id, -v_required,
          'pos_sale', v_order.id, NULL, p_client_op_id
        );
      END LOOP;
    ELSIF v_sku.inventory_policy = 'unlimited' THEN
      NULL;
    ELSE
      SELECT qty INTO v_stock
        FROM public.inv_stocks
       WHERE sku_id = v_sku.id AND location_id = v_shift.location_id
       FOR UPDATE;
      IF coalesce(v_stock, 0) < v_item.quantity THEN
        RAISE EXCEPTION 'SKU % is out of stock', v_sku.id;
      END IF;
      PERFORM public.inv_apply_movement(
        v_sku.id, v_shift.location_id, -v_item.quantity,
        'pos_sale', v_order.id,
        CASE WHEN v_sku.is_custom_price THEN v_sku.epc ELSE NULL END,
        p_client_op_id
      );
      IF v_sku.is_custom_price THEN
        UPDATE public.inv_skus SET sales_state = 'sold', updated_at = now() WHERE id = v_sku.id;
        UPDATE public.inv_epcs SET status = 'sold', current_location_id = NULL, last_seen_at = now()
         WHERE epc = v_sku.epc;
        UPDATE public.commerce_listings SET status = 'sold', sold_at = now(), updated_at = now()
         WHERE sku_id = v_sku.id AND status IN ('published', 'reserved');
      END IF;
    END IF;
  END LOOP;

  FOR v_tender IN
    SELECT tender.provider, tender.amount, tender.provider_transaction_id
      FROM jsonb_to_recordset(p_tenders)
        AS tender(provider text, amount numeric, provider_transaction_id text)
  LOOP
    INSERT INTO public.commerce_payments (
      order_id, provider, status, amount, provider_transaction_id, idempotency_key, paid_at
    ) VALUES (
      v_order.id, v_tender.provider, 'succeeded', v_tender.amount,
      v_tender.provider_transaction_id, p_client_op_id || ':' || v_tender.provider, now()
    ) RETURNING id INTO v_payment_id;
    INSERT INTO public.commerce_payment_events (
      payment_id, provider, provider_event_id, event_type,
      signature_verified, payload, processing_status, processed_at
    ) VALUES (
      v_payment_id, v_tender.provider,
      coalesce(v_tender.provider_transaction_id, p_client_op_id || ':' || v_tender.provider),
      'pos_payment_succeeded', true,
      jsonb_build_object('amount', v_tender.amount, 'shift_id', p_shift_id),
      'processed', now()
    );
    IF v_tender.provider = 'cash' THEN
      INSERT INTO public.pos_cash_movements (shift_id, order_id, type, amount, reason, operator_id)
      VALUES (p_shift_id, v_order.id, 'sale', v_tender.amount, 'POS sale', p_operator_id);
    END IF;
  END LOOP;

  SELECT jsonb_agg(jsonb_build_object(
           'sku_id', item.sku_id,
           'title', item.title_snapshot,
           'unit_price', item.unit_price,
           'quantity', item.quantity,
           'line_total', item.line_total,
           'category_code', item.category_code,
           'category_name', item.category_name_snapshot,
           'subcategory_code', item.subcategory_code,
           'subcategory_name', item.subcategory_name_snapshot
         ) ORDER BY item.created_at, item.id)
    INTO v_items_payload
    FROM public.commerce_order_items item
   WHERE item.order_id = v_order.id;

  v_receipt_no := (
    SELECT receipt_prefix FROM public.pos_registers WHERE id = v_shift.register_id
  ) || '-' || to_char(now(), 'YYYYMMDD') || '-' || right(v_order.order_no, 6);
  INSERT INTO public.pos_receipts (order_id, shift_id, receipt_no, payload)
  VALUES (
    v_order.id, p_shift_id, v_receipt_no,
    jsonb_build_object(
      'order_no', v_order.order_no,
      'receipt_no', v_receipt_no,
      'total_amount', v_order.total_amount,
      'paid_at', v_order.paid_at,
      'items', coalesce(v_items_payload, '[]'::jsonb)
    )
  );

  RETURN jsonb_build_object(
    'order_id', v_order.id,
    'order_no', v_order.order_no,
    'receipt_no', v_receipt_no,
    'replayed', false,
    'total_amount', v_order.total_amount,
    'items', coalesce(v_items_payload, '[]'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.pos_complete_sale_v3(p_shift_id uuid, p_operator_id uuid, p_client_op_id text, p_items jsonb, p_tenders jsonb, p_customer_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_discount_snapshot jsonb DEFAULT '{}'::jsonb, p_benefit_snapshot jsonb DEFAULT '{}'::jsonb, p_authorization_id uuid DEFAULT NULL::uuid, p_points_to_redeem integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order public.commerce_orders;
  v_shift public.pos_shifts;
  v_request jsonb;
  v_rules jsonb;
  v_result jsonb;
  v_snapshot jsonb;
  v_balance integer;
  v_subtotal numeric := 0;
  v_eligible numeric := 0;
  v_manual numeric := 0;
  v_value numeric;
  v_points_fen numeric;
  v_cap_fen numeric;
  v_points_unit integer;
  v_fen_unit integer;
  v_line record;
  v_running numeric := 0;
  v_prev_discount numeric := 0;
  v_next_discount numeric;
  v_prev_points integer := 0;
  v_next_points integer;
BEGIN
  IF p_client_op_id IS NULL OR btrim(p_client_op_id) = '' THEN RAISE EXCEPTION 'client operation id required'; END IF;
  IF p_points_to_redeem IS NULL OR p_points_to_redeem < 0 THEN RAISE EXCEPTION 'points_request_invalid'; END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'sale_recovery_isolation_unsupported';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('pos-sale:' || p_client_op_id, 0));
  IF EXISTS (SELECT 1 FROM public.pos_sale_cancellations WHERE client_op_id = p_client_op_id) THEN
    RAISE EXCEPTION 'sale_operation_cancelled';
  END IF;
  v_request := jsonb_build_object('shift_id', p_shift_id, 'operator_id', p_operator_id,
    'customer_id', p_customer_id, 'items', p_items, 'tenders', p_tenders,
    'discount', p_discount_snapshot, 'points', p_points_to_redeem);
  SELECT * INTO v_order FROM public.commerce_orders WHERE source_channel = 'pos' AND idempotency_key = p_client_op_id FOR UPDATE;
  IF FOUND THEN
    IF v_order.operator_id IS DISTINCT FROM p_operator_id OR v_order.pos_shift_id IS DISTINCT FROM p_shift_id
      OR v_order.customer_id IS DISTINCT FROM p_customer_id
      OR (v_order.metadata ? 'pos_sale_request' AND v_order.metadata->'pos_sale_request' IS DISTINCT FROM v_request)
      OR (NOT (v_order.metadata ? 'pos_sale_request') AND p_points_to_redeem <> 0) THEN
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    RETURN jsonb_build_object('order_id', v_order.id, 'order_no', v_order.order_no,
      'replayed', true, 'subtotal', v_order.subtotal, 'discount_total', v_order.discount_total,
      'total_amount', v_order.total_amount, 'points_redemption', v_order.benefit_snapshot->'points_redemption');
  END IF;
  SELECT * INTO v_shift FROM public.pos_shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND OR v_shift.status <> 'open' OR v_shift.operator_id IS DISTINCT FROM p_operator_id THEN
    RAISE EXCEPTION 'POS shift is not available';
  END IF;

  IF p_points_to_redeem = 0 THEN
    v_result := public.pos_complete_sale_without_points(p_shift_id,p_operator_id,p_client_op_id,p_items,p_tenders,
      p_customer_id,p_note,p_discount_snapshot,coalesce(p_benefit_snapshot,'{}') - 'points_redemption',p_authorization_id);
    UPDATE public.commerce_orders SET metadata = metadata || jsonb_build_object('pos_sale_request',v_request)
      WHERE id = (v_result->>'order_id')::uuid;
    RETURN v_result;
  END IF;

  IF p_customer_id IS NULL THEN RAISE EXCEPTION 'points_customer_required'; END IF;
  IF jsonb_typeof(p_tenders) IS DISTINCT FROM 'array' OR jsonb_array_length(p_tenders) = 0
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_tenders) t WHERE t->>'provider' IS DISTINCT FROM 'cash') THEN
    RAISE EXCEPTION 'points_async_not_supported';
  END IF;
  SELECT points INTO v_balance FROM public.pos_customer_wallets WHERE customer_id = p_customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'points_wallet_unavailable'; END IF;
  v_rules := public.pos_points_rules(p_customer_id);
  IF NOT (v_rules->>'customer_active')::boolean THEN RAISE EXCEPTION 'points_customer_inactive'; END IF;
  IF NOT (v_rules->>'enabled')::boolean THEN RAISE EXCEPTION 'points_rule_not_configured'; END IF;
  v_points_unit := (v_rules->>'points_per_unit')::integer;
  v_fen_unit := (v_rules->>'unit_fen')::integer;
  IF v_points_unit IS NULL OR v_fen_unit IS NULL OR v_points_unit <= 0 OR v_fen_unit <= 0 THEN
    RAISE EXCEPTION 'points_rule_not_configured';
  END IF;
  IF p_points_to_redeem > v_balance OR p_points_to_redeem % v_points_unit <> 0 THEN
    RAISE EXCEPTION 'points_balance_or_unit_invalid';
  END IF;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'sale requires items';
  END IF;
  -- Freeze prices/eligibility while both the quote and legacy stock transaction run.
  PERFORM 1 FROM public.inv_skus WHERE id IN
    (SELECT (item->>'sku_id')::uuid FROM jsonb_array_elements(p_items) item) ORDER BY id FOR UPDATE;
  SELECT sum(s.price_tier * i.quantity),
    coalesce(sum(s.price_tier * i.quantity) FILTER (WHERE s.discount_eligible AND s.sale_ownership = 'owned'),0)
    INTO v_subtotal, v_eligible FROM jsonb_to_recordset(p_items) i(sku_id uuid, quantity integer)
    JOIN public.inv_skus s ON s.id = i.sku_id;
  v_value := coalesce((p_discount_snapshot->>'value')::numeric,0);
  CASE coalesce(p_discount_snapshot->>'type','amount')
    WHEN 'amount' THEN v_manual := round(v_value,2);
    WHEN 'percentage' THEN
      IF v_value < 0 OR v_value > 100 THEN RAISE EXCEPTION 'discount value invalid'; END IF;
      v_manual := round(v_eligible * (1 - v_value / 100),2);
    WHEN 'final_price' THEN v_manual := round(v_subtotal - v_value,2);
    ELSE RAISE EXCEPTION 'discount type invalid';
  END CASE;
  IF v_manual < 0 OR v_manual > v_eligible THEN RAISE EXCEPTION 'discount exceeds eligible amount'; END IF;
  v_points_fen := (p_points_to_redeem / v_points_unit)::numeric * v_fen_unit;
  v_cap_fen := floor((v_eligible - v_manual) * 100 * (v_rules->>'cap_rate')::numeric);
  IF v_points_fen > v_cap_fen OR v_subtotal - v_manual - v_points_fen / 100 < 0.01 THEN
    RAISE EXCEPTION 'points_cap_exceeded';
  END IF;
  IF (v_manual + v_points_fen / 100 > 20 OR (v_manual + v_points_fen / 100) * 10 > v_eligible)
    AND NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = p_operator_id
      AND role::text IN ('super_admin','hq_operator','store_manager')) THEN
    IF NOT EXISTS (SELECT 1 FROM public.pos_authorizations a
      WHERE a.id = p_authorization_id AND a.operator_id = p_operator_id
        AND a.location_id = v_shift.location_id AND a.action = 'order_discount'
        AND a.status = 'approved' AND a.expires_at > now()
        AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = a.authorizer_id
          AND r.role::text IN ('super_admin','hq_operator','store_manager'))) THEN
      RAISE EXCEPTION 'discount authorization required for combined points discount';
    END IF;
  END IF;
  v_snapshot := v_rules || jsonb_build_object('applied_points',p_points_to_redeem,
    'discount_amount',v_points_fen / 100,'cap_basis','eligible_after_discount');
  v_result := public.pos_complete_sale_without_points(p_shift_id,p_operator_id,p_client_op_id,p_items,p_tenders,
    p_customer_id,p_note,jsonb_build_object('type','amount','value',v_manual + v_points_fen / 100,
      'reason',p_discount_snapshot->>'reason'),
    (coalesce(p_benefit_snapshot,'{}') - 'points_redemption') || jsonb_build_object('points_redemption',v_snapshot),p_authorization_id);
  SELECT * INTO v_order FROM public.commerce_orders WHERE id = (v_result->>'order_id')::uuid;
  UPDATE public.pos_customer_wallets SET points = points - p_points_to_redeem, updated_at = now()
    WHERE customer_id = p_customer_id RETURNING points INTO v_balance;
  INSERT INTO public.commerce_points_ledger(customer_id,delta,balance_after,source_type,source_id,idempotency_key,metadata)
    VALUES (p_customer_id,-p_points_to_redeem,v_balance,'pos_redemption',v_order.id::text,
      'pos-redemption:' || v_order.id,v_snapshot);
  UPDATE public.commerce_orders SET discount_snapshot = coalesce(p_discount_snapshot,'{}'),
    metadata = metadata || jsonb_build_object('pos_sale_request',v_request) WHERE id = v_order.id;

  -- Cumulative allocation conserves every fen and point, including the final line.
  FOR v_line IN SELECT * FROM public.commerce_order_items WHERE order_id = v_order.id ORDER BY id LOOP
    IF (v_line.discount_snapshot->>'eligible')::boolean THEN
      v_running := v_running + v_line.line_total;
      v_next_discount := floor((v_manual * 100 + v_points_fen) * v_running / v_eligible);
      v_next_points := floor(p_points_to_redeem::numeric * v_running / v_eligible);
      UPDATE public.commerce_order_items SET
        discount_total = (v_next_discount - v_prev_discount) / 100,
        line_total = line_total - (v_next_discount - v_prev_discount) / 100,
        discount_snapshot = discount_snapshot || jsonb_build_object('points_allocated',v_next_points - v_prev_points)
        WHERE id = v_line.id;
      v_prev_discount := v_next_discount;
      v_prev_points := v_next_points;
    END IF;
  END LOOP;
  UPDATE public.pos_receipts SET payload = payload || jsonb_build_object('points_redemption',v_snapshot,
    'items',(SELECT jsonb_agg(jsonb_build_object('sku_id',sku_id,'title',title_snapshot,
      'unit_price',unit_price,'quantity',quantity,'line_total',line_total,'discount_total',discount_total,
      'category_code',category_code,'category_name',category_name_snapshot,
      'subcategory_code',subcategory_code,'subcategory_name',subcategory_name_snapshot) ORDER BY created_at,id)
      FROM public.commerce_order_items WHERE order_id = v_order.id)) WHERE order_id = v_order.id;
  RETURN v_result || jsonb_build_object('points_redemption',v_snapshot,
    'items',(SELECT payload->'items' FROM public.pos_receipts WHERE order_id = v_order.id));
END;
$function$
